pub trait Complete<'a>:
    State<
    'a,
    Label: IsSetLabel<'a>,
    AddressModeU: IsSetAddressModeU,
    AddressModeV: IsSetAddressModeV,
    AddressModeW: IsSetAddressModeW,
    MagFilter: IsSetMagFilter,
    MinFilter: IsSetMinFilter,
    MipmapFilter: IsSetMipmapFilter,
    LodMinClamp: IsSetLodMinClamp,
    LodMaxClamp: IsSetLodMaxClamp,
    Compare: IsSetCompare,
    AnisotropyClamp: IsSetAnisotropyClamp,
    BorderColor: IsSetBorderColor,
>
{
}
impl<
        'a,
        CS: State<
            'a,
            Label: IsSetLabel<'a>,
            AddressModeU: IsSetAddressModeU,
            AddressModeV: IsSetAddressModeV,
            AddressModeW: IsSetAddressModeW,
            MagFilter: IsSetMagFilter,
            MinFilter: IsSetMinFilter,
            MipmapFilter: IsSetMipmapFilter,
            LodMinClamp: IsSetLodMinClamp,
            LodMaxClamp: IsSetLodMaxClamp,
            Compare: IsSetCompare,
            AnisotropyClamp: IsSetAnisotropyClamp,
            BorderColor: IsSetBorderColor,
        >,
    > Complete<'a> for CS
{
}
impl<'a, CS: Complete<'a>> SamplerDescriptorBuilder<'a, CS> {
    pub fn build(self) -> wgpu_27::SamplerDescriptor<'a> {
        wgpu_27::SamplerDescriptor {
            label: IsSetLabel::get(self.label),
            address_mode_u: IsSetAddressModeU::get(self.address_mode_u),
            address_mode_v: IsSetAddressModeV::get(self.address_mode_v),
            address_mode_w: IsSetAddressModeW::get(self.address_mode_w),
            mag_filter: IsSetMagFilter::get(self.mag_filter),
            min_filter: IsSetMinFilter::get(self.min_filter),
            mipmap_filter: IsSetMipmapFilter::get(self.mipmap_filter),
            lod_min_clamp: IsSetLodMinClamp::get(self.lod_min_clamp),
            lod_max_clamp: IsSetLodMaxClamp::get(self.lod_max_clamp),
            compare: IsSetCompare::get(self.compare),
            anisotropy_clamp: IsSetAnisotropyClamp::get(self.anisotropy_clamp),
            border_color: IsSetBorderColor::get(self.border_color),
        }
    }
    pub fn create_with(self, device: &wgpu_27::Device) -> wgpu_27::Sampler {
        device.create_sampler(&self.build())
    }
}
